#!/usr/bin/env python3
"""Find citations of unrooted modules (by module basename) across the citation surfaces."""
import os, re, json, collections

R = "/home/axel/LeanAlgebraicGeometry-Horizon"
P = os.path.join(R, "MainProjects/Algebraic-Jacobian-Challenge-Rebuild")
d = json.load(open("/tmp/reach.json"))
unrooted = d["unrooted"]; reachable = set(d["reachable"]); paths = d["paths"]

basenames = {m: m.split(".")[-1] for m in unrooted}
# some basenames are prefixes of others (DivSchemeHighWindowPencil vs ...PencilDivisor)
# match on word-ish boundary
pats = {m: re.compile(re.escape(b) + r'(?![A-Za-z0-9_])') for m, b in basenames.items()}

surfaces = []
# rooted lean modules
for m in reachable:
    surfaces.append(("ROOTED-LEAN", paths[m], m))
surfaces.append(("ROOTED-LEAN", os.path.join(P, "AlgebraicJacobian.lean"), "AlgebraicJacobian"))
# unrooted lean modules themselves (to build the unrooted-internal dep graph)
for m in unrooted:
    surfaces.append(("UNROOTED-LEAN", paths[m], m))
# informal, blueprint, hgraph, readme
for sub, tag in [("informal","INFORMAL"), ("blueprint","BLUEPRINT"), ("hgraph","HGRAPH")]:
    base = os.path.join(P, sub)
    for dp, dn, fns in os.walk(base):
        for fn in fns:
            if fn.endswith((".md",".tex",".json",".yaml",".yml",".txt")):
                surfaces.append((tag, os.path.join(dp,fn), fn))
for f in ["README.md"]:
    surfaces.append(("README", os.path.join(P,f), f))
for f in ["roadmap.md","README.md"]:
    surfaces.append(("WS-DOC", os.path.join(R,f), f))
surfaces.append(("ROADMAP-JSON", "/tmp/roadmap_all.json", "roadmap"))
surfaces.append(("INBOX-JSON", "/tmp/inbox_all.json", "inbox"))

hits = collections.defaultdict(list)
for tag, path, label in surfaces:
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            txt = f.read()
    except OSError:
        continue
    lines = txt.split("\n")
    for m, pat in pats.items():
        if basenames[m] not in txt: continue
        for i, line in enumerate(lines, 1):
            if pat.search(line):
                hits[m].append((tag, path, i, line.strip()[:300]))

json.dump({k: v for k, v in hits.items()}, open("/tmp/cites.json","w"), indent=1)

print(f"{'module':60s} rootedLean informal roadmap inbox bp/hg unrootedLean")
for m in unrooted:
    h = hits.get(m, [])
    c = collections.Counter(t for t,_,_,_ in h)
    # exclude self-references in the module's own file
    selfrefs = sum(1 for t,p,i,l in h if p == paths[m])
    print(f"{m.replace('AlgebraicJacobian.',''):60s} "
          f"{c['ROOTED-LEAN']:>6d} {c['INFORMAL']:>8d} {c['ROADMAP-JSON']:>7d} {c['INBOX-JSON']:>5d} "
          f"{c['BLUEPRINT']+c['HGRAPH']:>5d} {c['UNROOTED-LEAN']-selfrefs:>7d}")

